// frontend/src/services/api.js

const BASE_URL = process.env.REACT_APP_API_URL || "http://localhost:5000/api";

export async function fetchStats() {
  const res = await fetch(`${BASE_URL.replace("/api", "")}/api/stats`);
  return res.json();
}

export async function fetchFraudCycles() {
  const res = await fetch(`${BASE_URL}/fraud/cycles`);
  return res.json();
}

export async function fetchRiskLogs() {
  const res = await fetch(`${BASE_URL}/fraud/logs`);
  return res.json();
}

export async function fetchTraders() {
  const res = await fetch(`${BASE_URL}/traders`);
  return res.json();
}

export async function fetchTraderById(id) {
  const res = await fetch(`${BASE_URL}/traders/${id}`);
  return res.json();
}

export async function fetchTrades(page = 1) {
  const res = await fetch(`${BASE_URL}/trades?page=${page}&limit=50`);
  return res.json();
}

export async function insertTrade(tradeData) {
  const res = await fetch(`${BASE_URL}/trades`, {
    method:  "POST",
    headers: { "Content-Type": "application/json" },
    body:    JSON.stringify(tradeData)
  });
  return res.json();
}
